fn pal_necro(ch: char) -> Option<Color> {
    Some(match ch {
        'K' => c(10,8,16),
        'r' => c(48,34,74),
        'R' => c(30,22,50),
        'm' => c(84,62,124),
        'b' => c(226,220,198),
        'B' => c(176,168,146),
        'e' => c(93,255,122),
        'E' => c(216,255,224),
        'k' => c(14,10,20),
        'w' => c(80,56,38),
        'W' => c(52,36,26),
        'g' => c(150,255,170),
        'x' => c(120,200,140),
        _ => return None,
    })
}

